import { stat } from 'node:fs/promises';
import { resolve, relative, join, extname, isAbsolute, sep } from 'node:path';
import { fileURLToPath } from 'node:url';

const DATA_DIR = resolve(new URL('.', import.meta.url), 'data');

function normalizeAndCheck(path) {
  if (typeof path !== 'string' || path.length === 0) {
    throw new Error('path is required');
  }
  if (isAbsolute(path)) {
    throw new Error('absolute paths are not allowed');
  }
  const abs = resolve(DATA_DIR, path);
  const rel = relative(DATA_DIR, abs);
  if (rel === '' || rel === '.') {
    throw new Error('invalid path');
  }
  if (rel.startsWith('..') || isAbsolute(rel)) {
    throw new Error('path traversal is not allowed');
  }
  return abs;
}

export async function listTools() {
  return [
    {
      name: 'file_metadata',
      description: 'Return metadata (relative path, byte size, lowercase extension) for a file under the workspace data directory.',
      inputSchema: {
        type: 'object',
        properties: {
          path: {
            type: 'string',
            description: 'Path of the file relative to the workspace data directory.'
          }
        },
        required: ['path'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'file_metadata') {
    throw new Error(`Unknown tool: ${name}`);
  }
  const { path } = args;
  if (typeof path !== 'string' || path.length === 0) {
    throw new Error('path is required');
  }
  const abs = normalizeAndCheck(path);
  let info;
  try {
    info = await stat(abs);
  } catch (e) {
    throw new Error('file not found');
  }
  if (!info.isFile()) {
    throw new Error('not a file');
  }
  const rel = relative(DATA_DIR, abs);
  const ext = extname(abs).toLowerCase();
  const text = `relative path: ${rel}\nsize: ${info.size} bytes\nextension: ${ext}`;
  return {
    content: [{ type: 'text', text }]
  };
}

